public class ItemValue {public bool HasModSlots;public bool HasMods(){return false;}public void Write(BinaryWriter writer){new ItemStack{itemValue=this,count=1}.Write(writer);}
 public int type;public Dictionary<string,object> Metadata=new Dictionary<string,object>();public bool IsEmpty(){return type==0;}public bool HasMetadata(string k){return Metadata.ContainsKey(k);}public void SetMetadata(string k,object v){Metadata[k]=v;}public bool TryGetMetadata<T>(string k,out T v){object raw;if(Metadata.TryGetValue(k,out raw)&&raw is T){v=(T)raw;return true;}v=default(T);return false;}public ItemValue Clone(){return new ItemValue{type=type,Metadata=new Dictionary<string,object>(Metadata)};}}
public class ItemStack {public static ItemStack Empty=new ItemStack();public bool IsEmpty(){return count<=0||itemValue==null||itemValue.IsEmpty();}public ItemValue itemValue=new ItemValue();public int count;public ItemStack(){}public ItemStack(ItemValue v,int n){itemValue=v;count=n;}public ItemStack(int t,int n){itemValue.type=t;count=n;}public ItemStack Clone(){return new ItemStack{itemValue=itemValue.Clone(),count=count};}public void Write(BinaryWriter w){w.Write(itemValue.type);w.Write(count);w.Write(itemValue.Metadata.Count);foreach(var p in itemValue.Metadata){w.Write(p.Key);w.Write(p.Value is int);if(p.Value is int)w.Write((int)p.Value);else w.Write((string)p.Value);}}public ItemStack Read(BinaryReader r){itemValue.type=r.ReadInt32();count=r.ReadInt32();int n=r.ReadInt32();for(int i=0;i<n;i++){string k=r.ReadString();bool number=r.ReadBoolean();itemValue.Metadata[k]=number?(object)r.ReadInt32():r.ReadString();}return this;}}
