// Native item codec double: uses the fixture ItemStack format, not the game's ItemValue codec.
public static class RebirthNativeItemCodec {
 public static string Encode(ItemValue value){using(var stream=new MemoryStream()){using(var w=new BinaryWriter(stream,Encoding.UTF8,true))new ItemStack(value,1).Write(w);return Convert.ToBase64String(stream.ToArray());}}
 public static bool TryDecode(string data,out ItemValue value){value=null;try{using(var stream=new MemoryStream(Convert.FromBase64String(data)))using(var r=new BinaryReader(stream)){var stack=new ItemStack().Read(r);if(stream.Position!=stream.Length||stack.itemValue.IsEmpty())return false;value=stack.itemValue;return true;}}catch{return false;}}
}
